const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');const ctx={window:{},document:{documentElement:{lang:'uk'},addEventListener(){}},profileStorage:{getItem:()=>null}};vm.createContext(ctx);for(const f of ['gear-data','gear-dialogue-audio','gear-conversation'])vm.runInContext(fs.readFileSync('assets/adaptive/'+f+'.js','utf8'),ctx);const d=ctx.window.DEUTSCH_GEAR_DATA,c=ctx.window.DEUTSCH_GEAR_CONVERSATION;
assert.equal(d.lessons.length,7);for(const l of d.lessons){assert.equal(l.cards.length,6);assert.equal(new Set(l.cards.map(c=>c.de)).size,6);assert(l.rule.every(s=>s.length>150));assert(d.actors.some(a=>a.id===l.actor))}assert.equal(d.awards.length,7);assert.equal(new Set(d.awards.map(a=>a.lesson)).size,7);
assert(d.lessons[1].cards.every(c=>!c.de.includes('einen')));assert(d.lessons[3].cards.slice(0,2).every(c=>c.de.includes('einen')));assert(d.lessons[2].cards[4].de.includes('mein Buch'));assert.equal(c.match('rucksack','EINEN RUCKSACK, BITTE!'),'Einen Rucksack, bitte.');assert.equal(c.match('karte','Ich möchte eine Karte, bitte.'),'Ich möchte eine Karte, bitte.');assert.equal(c.match('rucksack','Ein Rucksack, bitte.'),null);assert.equal(c.match('karte','Einen Rucksack, bitte.'),null);assert(c.audioFor('greta','hello').includes('greta-lola'));assert(c.audioFor('you','rucksack').includes('oleksii-dylan-gear'));assert.equal(c.availability().ready,12);assert.equal(c.audioFor('you','hello').includes('oleksii-dylan'),true);
const orders=new Set();for(let i=0;i<50;i++){const p=c.plan();assert.equal(p.length,6);assert.equal(p[0],'hello');assert.equal(p[4],'thanks');assert.equal(p[5],'bye');assert.notEqual(c.plan(p.slice(1,4)).slice(1,4).join('|'),p.slice(1,4).join('|'));orders.add(p.join('|'))}assert(orders.size>1);
const m=JSON.parse(fs.readFileSync('audio/recording/gear-island-v1/manifest.json'));assert.equal(m.greta.lines.length,4);assert.equal(m.learner_oleksii.lines.length,3);assert(m.neutral.lines.length>0);assert(m.neutral.lines.every(l=>l.path&&fs.existsSync(l.path)));assert.equal(m.greta.voiceName,'Lola - Fantasy & LitRPG');assert.equal(m.status,'recorded');for(const role of ['greta','you'])for(const id of ['hello','rucksack','karte','seil','thanks','bye'])assert(fs.existsSync(c.audioFor(role,id)));assert.equal(c.audioFor('you','rucksack','Ich möchte einen Rucksack, bitte.'),null);
console.log('PASS gear curriculum: seven six-card lessons, full theory, staged articles/accusative, distinct roles/awards, meaningful exact replies, shuffled item plan and complete voice manifest and exact original role clips');
